import heapq


def minimumDeviation(nums):
    h = []
    mn = None
    for x in nums:
        if x % 2:
            x *= 2
        h.append(-x)
        if mn is None or x < mn:
            mn = x
    heapq.heapify(h)
    best = -h[0] - mn
    while True:
        x = -h[0]
        if x % 2:
            break
        x //= 2
        heapq.heapreplace(h, -x)
        if x < mn:
            mn = x
        best = min(best, -h[0] - mn)
    return best
